/*
  Solo il simbolo, ritagliato sul suo riquadro: serve dove non c'è spazio per
  la parola (icona del menu mobile, favicon, elenchi).
*/
export function LogoMark({
  tone = "auto",
  gradientId = "ip-mark-gradient",
  ...props
}: Omit<LogoProps, "withPayoff">) {
  const c = palette[tone];

  return (
    <svg viewBox="3 4 88 108" role="img" aria-label="Ideapubblica" {...props}>
      <defs>
        <linearGradient
          id={gradientId}
          gradientUnits="userSpaceOnUse"
          x1="14.89"
          y1="110.11"
          x2="67.05"
          y2="19.75"
        >
          {c.stops.map((color, i) => (
            <stop key={color + i} offset={offsets[i]} stopColor={color} />
          ))}
        </linearGradient>
      </defs>
      <path fill={`url(#${gradientId})`} d="M57.33 85.17A9.71 9.71 0 1 1 44 99.3a9.71 9.71 0 0 1 13.33-14.13m3.53-63.38q-4.43.03-8.45 1.26-.2.06-.4.06a1.55 1.55 0 0 1-1.53-1.88q.39-1.53.4-3.18a13.24 13.24 0 1 0-14.51 13.17 1.55 1.55 0 0 1 1.02 2.42 29.1 29.1 0 0 0-2.65 30.39 9.73 9.73 0 0 1-10.97 13.88q-1.7-.37-3.5-.37A16.58 16.58 0 1 0 36.2 89.47v-.01a9.72 9.72 0 0 1 13.04-11.63l.03.01a29.23 29.23 0 1 0 11.59-56.05" />
    </svg>
  );
}

export default Logo;
